(function(){'use strict';var data=window.QEVA_HISTORY||[],root=document.getElementById('timeline'),controls=document.getElementById('history-controls');if(!root)return;function esc(s){return String(s).replace(/[&<>"']/g,function(m){return({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'})[m]})}function render(branch){root.innerHTML='';data.filter(function(x){return !branch||x.branch===branch}).sort(function(a,b){return a.year-b.year}).forEach(function(x){var a=document.createElement('article');a.className='milestone';a.innerHTML='<span class="year">'+esc(x.date)+'</span><p class="eyebrow">'+esc(x.branch.toUpperCase())+'</p><h2>'+esc(x.title)+'</h2><p><strong>'+esc(x.people)+'</strong></p><p>'+esc(x.note)+'</p>'+(x.qeva&&x.qeva.length?'<p class="links">QEVA links: '+x.qeva.map(esc).join(' · ')+'</p>':'');root.appendChild(a)})}render('');if(controls)controls.addEventListener('click',function(e){var b=e.target.closest('button');if(!b)return;Array.prototype.forEach.call(controls.querySelectorAll('button'),function(x){x.setAttribute('aria-pressed','false')});b.setAttribute('aria-pressed','true');render(b.dataset.branch||'')})})();
